def shade(cell, fill):
    tcPr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),fill); tcPr.append(shd)

def borders(cell, color='B7B7B7'):
    tcPr=cell._tc.get_or_add_tcPr(); el=tcPr.first_child_found_in('w:tcBorders')
    if el is None: el=OxmlElement('w:tcBorders'); tcPr.append(el)
    for edge in ('top','left','bottom','right','insideH','insideV'):
        n=OxmlElement('w:'+edge); n.set(qn('w:val'),'single'); n.set(qn('w:sz'),'4'); n.set(qn('w:color'),color); el.append(n)

def set_cell_margins(cell, top=55, start=60, bottom=55, end=60):
    tcPr=cell._tc.get_or_add_tcPr(); m=tcPr.first_child_found_in('w:tcMar')
    if m is None: m=OxmlElement('w:tcMar'); tcPr.append(m)
    for tag,val in [('top',top),('start',start),('bottom',bottom),('end',end)]:
        n=OxmlElement('w:'+tag); n.set(qn('w:w'),str(val)); n.set(qn('w:type'),'dxa'); m.append(n)

def set_columns(section, n=2, space=252):
    sectPr=section._sectPr; cols=sectPr.xpath('./w:cols')
    el=cols[0] if cols else OxmlElement('w:cols')
    if not cols: sectPr.append(el)
    el.set(qn('w:num'),str(n)); el.set(qn('w:space'),str(space)); el.set(qn('w:equalWidth'),'1')

def add_table(doc, data, caption=None, widths=None):
    if caption:
        p=doc.add_paragraph(caption); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.keep_with_next=True
        for r in p.runs: r.font.size=Pt(7.5); r.font.bold=True
    ncols=len(data[0]); t=doc.add_table(rows=len(data),cols=ncols); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.autofit=False
    trPr=t.rows[0]._tr.get_or_add_trPr(); hdr=OxmlElement('w:tblHeader'); hdr.set(qn('w:val'),'true'); trPr.append(hdr)
    if widths is None: widths=[3.42/ncols]*ncols
    # python-docx initializes the table grid to the full text width even when
    # cell widths are later narrowed. LibreOffice then clips the first-column
    # text when the table is rendered inside an IEEE two-column section. Keep
    # the grid and cell widths identical so Word and PDF renderers agree.
    grid_cols=t._tbl.tblGrid.gridCol_lst
    for j,width in enumerate(widths):
        grid_cols[j].set(qn('w:w'),str(round(width*1440)))
    for i,row in enumerate(data):
        for j,val in enumerate(row):
            c=t.cell(i,j); c.width=Inches(widths[j]); c.text=str(val); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            tcW=c._tc.get_or_add_tcPr().first_child_found_in('w:tcW')
            tcW.set(qn('w:w'),str(round(widths[j]*1440))); tcW.set(qn('w:type'),'dxa')
            set_cell_margins(c); borders(c)
            for p in c.paragraphs:
                p.alignment=WD_ALIGN_PARAGRAPH.CENTER if j==0 or i==0 else WD_ALIGN_PARAGRAPH.LEFT
                p.paragraph_format.space_after=Pt(0); p.paragraph_format.line_spacing=0.95
                for r in p.runs:
                    r.font.name='Times New Roman'; r.font.size=Pt(6.7); r.font.bold=(i==0)
                    r.font.color.rgb=RGBColor(255,255,255) if i==0 else RGBColor(0,0,0)
            shade(c,'1F4E79' if i==0 else ('EEF3F7' if i%2==0 else 'FFFFFF'))
    doc.add_paragraph().paragraph_format.space_after=Pt(0)
    return t

def add_figure(doc, filename, caption, width=3.35):
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.keep_with_next=True
    shape=p.add_run().add_picture(str(ASSET/filename),width=Inches(width))
    shape._inline.docPr.set('descr',caption)
    c=doc.add_paragraph(caption); c.alignment=WD_ALIGN_PARAGRAPH.CENTER
    c.paragraph_format.space_after=Pt(3)
    for r in c.runs: r.font.size=Pt(7.2); r.font.italic=True

def add_heading(doc, text):
    p=doc.add_paragraph(text); p.style='Heading 1'; p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.keep_with_next=True
    return p

def add_body(doc, text):
    p=doc.add_paragraph(text, style='Text'); p.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.first_line_indent=Inches(.14)
    if text.startswith('Algorithm 1 RecompositionFrontier'):
        p.alignment=WD_ALIGN_PARAGRAPH.LEFT; p.paragraph_format.first_line_indent=Inches(0)
        for rr in p.runs: rr.font.name='Liberation Mono'; rr.font.size=Pt(7.2)
    return p

