# Compact result tables are generated from the audited CSV rather than transcribed.
import pandas as pd
h=pd.read_csv(ROOT/'results'/'headline.csv')
order=['static','retry','react','replan','self_heal','unconstrained','fa_mas']
h=h.set_index('baseline').loc[order].reset_index()
headline=[['Policy','Complete','Accept.','Unsafe','Latency','Cost']]
for _,r in h.iterrows():
    headline.append([r.baseline.replace('_',' '),f'{100*r.success:.1f}%',f'{100*r.acceptable:.1f}%',f'{100*r.unsafe:.1f}%',f'{r.latency:.0f}',f'{r.cost:.2f}'])
for page in PAGES:
    if page['title']=='IX RESULTS':
        page['result_table']=headline

c=pd.read_csv(ROOT/'results'/'paired_comparisons.csv')
paired=[['Baseline','Δ complete','95% CI','Δ acceptable','Δ unsafe']]
for baseline in order[:-1]:
    z=c[c.baseline.eq(baseline)].set_index('metric')
    def pct(metric): return 100*z.loc[metric,'effect_fa_mas_minus_baseline']
    lo=100*z.loc['task_success','ci_low']; hi=100*z.loc['task_success','ci_high']
    paired.append([baseline.replace('_',' '),f'{pct("task_success"):+.2f}',f'[{lo:+.2f}, {hi:+.2f}]',f'{pct("acceptable_outcome"):+.2f}',f'{pct("unsafe_side_effect"):+.2f}'])
a=pd.read_csv(ROOT/'results'/'ablations.csv')
ablation=[['Variant','Complete','Accept.','Unsafe','Localized']]
for _,r in a.iterrows():
    ablation.append([r.ablation.replace('_',' '),f'{100*r.task_success:.2f}',f'{100*r.acceptable_outcome:.2f}',f'{100*r.unsafe_side_effect:.2f}',f'{100*r.localized:.2f}'])
for page in PAGES:
    if page['title']=='IX RESULTS CONTINUED':
        page['paired_table']=paired; page['ablation_table']=ablation

